def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n == 99:
        return 'D'

    my, opp = zip(*history)
    last_my, last_opp = history[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    retal = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i + 1] == 'D':
            retal += 1

    if last_opp == 'D':
        if opp_d >= n * 0.7:
            return 'D'
        if n >= 2 and 'D' in my[-2:]:
            return 'C'
        return 'D'

    if last_my == 'D':
        if retal > 0:
            return 'C'
        return 'D'

    if opp_d == 0:
        if n >= 5 and n % 5 == 0:
            return 'D'
        return 'C'

    return 'C'
